<?php declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';require_vendor();$vendor=vendor_user();$s=db()->prepare('SELECT COUNT(*) total,COALESCE(SUM(redeemed_at>=CURDATE()),0) today,COUNT(DISTINCT user_id) customers FROM gift_redemptions WHERE vendor_id=?');$s->execute([$vendor['vendor_id']]);$stats=$s->fetch();$r=db()->prepare('SELECT gr.redemption_id,g.name gift,u.name user_name,rc.code_reference,gr.redeemed_at FROM gift_redemptions gr JOIN gifts g ON g.id=gr.gift_id JOIN users u ON u.id=gr.user_id JOIN reward_codes rc ON rc.id=gr.reward_code_id WHERE gr.vendor_id=? ORDER BY gr.id DESC LIMIT 50');$r->execute([$vendor['vendor_id']]);$rows=$r->fetchAll();$notices=take_flashes();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendor dashboard · Hunter</title><link rel="stylesheet" href="<?=e(app_url('/assets/css/style.css'))?>"></head><body><header class="vendor-top"><div><strong><?=e($vendor['shop_name'])?></strong><small><?=e($vendor['vendor_code'])?></small></div><nav><a class="btn" href="<?=e(app_url('/vendor/redeem.php'))?>">Redeem code</a><form method="post" action="<?=e(app_url('/vendor/logout.php'))?>"><?=csrf_field()?><button class="btn secondary">Sign out</button></form></nav></header><main class="vendor-content"><?php foreach($notices as $n):?><div class="alert <?=e($n['type'])?>"><?=e($n['message'])?></div><?php endforeach?><div class="grid stats"><div class="card"><span class="label">Total redemptions</span><span class="value"><?=e($stats['total'])?></span></div><div class="card"><span class="label">Today</span><span class="value"><?=e($stats['today'])?></span></div><div class="card"><span class="label">Customers served</span><span class="value"><?=e($stats['customers'])?></span></div></div><section class="panel"><h2>Recent redemptions</h2><div class="table-wrap"><table><thead><tr><th>Redemption</th><th>Code reference</th><th>Gift</th><th>Customer</th><th>Time</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['redemption_id'])?></td><td><?=e($r['code_reference'])?></td><td><?=e($r['gift'])?></td><td><?=e($r['user_name'])?></td><td><?=e($r['redeemed_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No codes redeemed yet.</div><?php endif?></div></section></main></body></html>
